<style>
.exec .exec-chart-panel{position:relative;isolation:isolate;padding:clamp(20px,3vw,34px);margin:12px 0 26px;background:radial-gradient(ellipse at 85% 0,#31576655,transparent 60%),linear-gradient(140deg,#1d303f,#14232f 70%);border-color:#6b8e9f80;box-shadow:inset 0 1px #d7edf81f,0 16px 38px #00000018;overflow:hidden}.exec .exec-chart-panel:before{content:"";position:absolute;inset:0 10% auto;height:1px;background:linear-gradient(90deg,transparent,#d3efedaa,transparent)}.exec .exec-chart-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:26px}.exec .exec-chart-heading h3{font-size:clamp(24px,2.6vw,34px);margin:8px 0;line-height:1.15}.exec .exec-chart-total{text-align:right;flex-shrink:0;padding-left:26px;border-left:1px solid #8db2c233}.exec .exec-chart-total strong{display:block;font-size:clamp(32px,4vw,48px);font-weight:600;letter-spacing:-.045em;color:#caf3ec;line-height:1.1}.exec .exec-chart-total span,.exec .exec-chart-total small{display:block;color:#c1d4df;font-size:12px;line-height:1.8}.exec .exec-chart-total small{color:var(--muted);font-size:11px}.exec .exec-chart-legend{display:flex;gap:12px 26px;flex-wrap:wrap;margin-bottom:22px;color:#d7e7ef;font-size:12px}.exec .exec-chart-legend span,.exec .exec-chart-category>span{display:flex;gap:10px;align-items:center}.exec .exec-chart-legend i,.exec .exec-chart-category i{width:9px;height:9px;flex:0 0 9px;border-radius:3px;background:var(--series-color);box-shadow:0 0 12px color-mix(in srgb,var(--series-color),transparent 60%)}.exec .exec-chart-svg{width:100%;min-width:680px;display:block;font-family:inherit}.exec .exec-chart-grid{stroke:#9fb7c6;stroke-opacity:.13;stroke-dasharray:3 5}.exec .exec-chart-axis{fill:#b7cad8;font-size:12px}.exec .exec-chart-label{fill:#e0ebf2;font-size:13px;font-weight:500}.exec .exec-chart-mark,.exec .exec-chart-segment{transition:filter .18s,opacity .18s}.exec .exec-chart-mark:hover,.exec .exec-chart-segment:hover{filter:brightness(1.25)}.exec .exec-chart-orbit-layout{display:grid;grid-template-columns:minmax(240px,34%) 1fr;align-items:center;gap:clamp(20px,5vw,64px)}.exec .exec-chart-orbit{width:100%;max-width:360px;justify-self:center;font-family:inherit}.exec .exec-chart-ring-value{fill:#e9f7f6;font-size:42px;font-weight:600;letter-spacing:-2px}.exec .exec-chart-ring-label{fill:#a2bdcd;font-size:9px;letter-spacing:1.6px}.exec .exec-chart-distribution{display:grid;gap:17px}.exec .exec-chart-category{display:flex;justify-content:space-between;gap:15px;font-size:13px;color:#d6e5ed}.exec .exec-chart-category strong{font-variant-numeric:tabular-nums;color:#e9f7f6}.exec .exec-chart-track{height:5px;border-radius:5px;background:#91b1c014;margin-top:9px;overflow:hidden}.exec .exec-chart-track>span{display:block;height:100%;background:var(--series-color);border-radius:5px}.exec .exec-chart-note{font-size:12px;color:#a9c0cf;margin-top:20px;max-width:1050px}.exec .exec-chart-data{border-top:1px solid #8baabc26;margin-top:18px;padding-top:3px}.exec .exec-chart-data>summary{font-size:12px;color:#bfe1e3}.exec .exec-chart-data table{font-variant-numeric:tabular-nums}@media(max-width:680px){.exec .exec-chart-heading{align-items:flex-start;gap:12px}.exec .exec-chart-total{padding-left:14px;max-width:135px}.exec .exec-chart-total small{font-size:10px}.exec .exec-chart-orbit-layout{grid-template-columns:1fr;gap:18px}.exec .exec-chart-orbit{max-width:270px}.exec .exec-chart-heading h3{font-size:25px}.exec .exec-chart-heading .eyebrow{font-size:9px;letter-spacing:.14em}}
</style>
